CREATE OR REPLACE FUNCTION public.admin_reject_featured_request(p_admin_id uuid, p_request_id uuid, p_admin_note text DEFAULT NULL::text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if not public.meshwar_is_admin(p_admin_id) then
    raise exception 'not authorized';
  end if;

  update public.merchant_featured_requests
  set status='rejected',reviewed_by=p_admin_id,reviewed_at=now(),
      admin_note=nullif(trim(p_admin_note),''),updated_at=now()
  where id=p_request_id and status='pending';

  if not found then raise exception 'pending request not found'; end if;
  return true;
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_approve_featured_request(p_admin_id uuid, p_request_id uuid, p_store_id uuid, p_start_date timestamp with time zone, p_end_date timestamp with time zone, p_admin_note text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  r public.merchant_featured_requests%rowtype;
  v_slot uuid;
begin
  if p_admin_id is null or not public.meshwar_is_admin(p_admin_id) then
    raise exception 'not authorized';
  end if;
  if p_end_date<=p_start_date then raise exception 'end_date must be after start_date'; end if;

  select * into r
  from public.merchant_featured_requests
  where id=p_request_id
  for update;

  if not found then raise exception 'request not found'; end if;
  if r.status<>'pending' then raise exception 'request already reviewed'; end if;
  if p_store_id is null then raise exception 'store_id is required'; end if;
  if r.store_id is not null and p_store_id<>r.store_id then
    raise exception 'selected store does not match request store';
  end if;
  if not exists(select 1 from public.local_stores s where s.id=p_store_id and coalesce(s.is_active,true)=true) then
    raise exception 'store not found or inactive';
  end if;

  insert into public.merchant_featured_slots(
    store_id,merchant_id,slot_type,banner_url,store_logo,store_name,item_ids,start_date,end_date,is_active
  ) values (
    p_store_id,null,r.slot_type,r.banner_url,r.store_logo,r.store_name,r.item_ids,p_start_date,p_end_date,true
  ) returning id into v_slot;

  update public.merchant_featured_requests
  set store_id=p_store_id,status='approved',approved_slot_id=v_slot,reviewed_by=p_admin_id,reviewed_at=now(),
      admin_note=nullif(trim(p_admin_note),''),updated_at=now()
  where id=p_request_id;

  return v_slot;
end;
$function$

CREATE OR REPLACE FUNCTION private.v112_require_reward_actor(p_actor_id text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
declare
  v_role text;
begin
  select lower(trim(coalesce(e.role::text, '')))
    into v_role
  from public.employees e
  where e.id::text = trim(coalesce(p_actor_id, ''))
  limit 1;

  if v_role not in ('admin', 'employee', 'أدمن', 'ادمن', 'موظف') then
    raise exception 'REWARD_ACTOR_NOT_AUTHORIZED' using errcode = '42501';
  end if;
  return v_role;
end;
$function$

CREATE OR REPLACE FUNCTION public.adjust_customer_reward_balance(p_customer_id uuid, p_amount numeric, p_currency text, p_actor_id text, p_note text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
declare
  v_currency text := private.v112_reward_currency(p_currency);
  v_customer public.customers%rowtype;
  v_current numeric;
  v_next numeric;
  v_entry jsonb;
begin
  perform private.v112_require_reward_actor(p_actor_id);
  if v_currency not in ('USD', 'IQD', 'TRY') then
    raise exception 'REWARD_CURRENCY_NOT_SUPPORTED' using errcode = '22023';
  end if;
  if coalesce(p_amount, 0) = 0 then
    raise exception 'REWARD_AMOUNT_REQUIRED' using errcode = '22023';
  end if;

  select * into v_customer
  from public.customers
  where id = p_customer_id
  for update;
  if not found then raise exception 'CUSTOMER_NOT_FOUND' using errcode = 'P0002'; end if;

  v_current := coalesce(nullif(v_customer.reward_balances ->> v_currency, '')::numeric, 0);
  v_next := v_current + p_amount;
  if v_next < 0 then raise exception 'REWARD_BALANCE_INSUFFICIENT' using errcode = '22003'; end if;

  v_entry := jsonb_strip_nulls(jsonb_build_object(
    'amount', p_amount,
    'currency', v_currency,
    'type', case when p_amount > 0 then 'grant' else 'withdraw' end,
    'date', now(),
    'actor_id', p_actor_id,
    'note', nullif(trim(coalesce(p_note, '')), '')
  ));

  update public.customers
  set reward_balances = jsonb_set(coalesce(reward_balances, '{}'::jsonb), array[v_currency], to_jsonb(v_next), true),
      rewards_log = coalesce(rewards_log, '[]'::jsonb) || jsonb_build_array(v_entry)
  where id = p_customer_id;

  return jsonb_build_object('customer_id', p_customer_id, 'currency', v_currency,
    'balance', v_next, 'reward_balances', jsonb_set(coalesce(v_customer.reward_balances, '{}'::jsonb), array[v_currency], to_jsonb(v_next), true));
end;
$function$

CREATE OR REPLACE FUNCTION private.require_employee_session_v143(p_session_token text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'extensions', 'pg_temp'
AS $function$
declare
  v_employee_id text;
begin
  if trim(coalesce(p_session_token, '')) = '' then
    raise exception 'EMPLOYEE_SESSION_REQUIRED';
  end if;

  select s.employee_id into v_employee_id
  from public.employee_sessions_v143 s
  where s.token_hash = digest(p_session_token, 'sha256')
    and s.revoked_at is null
    and s.expires_at > now()
  limit 1;

  if v_employee_id is null then
    raise exception 'EMPLOYEE_SESSION_INVALID';
  end if;

  update public.employee_sessions_v143
  set last_seen_at = now()
  where token_hash = digest(p_session_token, 'sha256');

  return v_employee_id;
end;
$function$

CREATE OR REPLACE FUNCTION private.require_admin_session_v147(p_session_token text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'extensions', 'pg_temp'
AS $function$
                            declare
                              v_admin_id text;
                              begin
                                if trim(coalesce(p_session_token, '')) = '' then
                                    raise exception 'ADMIN_SESSION_REQUIRED';
                                      end if;

                                        select s.admin_id into v_admin_id
                                          from public.admin_sessions_v147 s
                                            where s.token_hash = digest(p_session_token, 'sha256')
                                                and s.revoked_at is null
                                                    and s.expires_at > now()
                                                      limit 1;

                                                        if v_admin_id is null then
                                                            raise exception 'ADMIN_SESSION_INVALID';
                                                              end if;

                                                                update public.admin_sessions_v147
                                                                  set last_seen_at = now()
                                                                    where token_hash = digest(p_session_token, 'sha256');

                                                                      return v_admin_id;
                                                                      end;
                                                                      $function$
